describe('Health Check API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('GET /api/health', () => {
    it('should return healthy status when all services are up', async () => {
      mockStorage.getSites.mockResolvedValue([]);
      mockBlockchainService.isEnabled.mockReturnValue(true);
      
      const startTime = Date.now();
      await mockStorage.getSites();
      const dbLatency = Date.now() - startTime;
      
      const health = {
        status: 'healthy',
        checks: {
          database: { status: 'healthy', latency: `${dbLatency}ms` },
          blockchain: { status: mockBlockchainService.isEnabled() ? 'connected' : 'disconnected' },
        },
      };
      
      expect(health.status).toBe('healthy');
      expect(health.checks.blockchain.status).toBe('connected');
    });

    it('should return unhealthy status when database fails', async () => {
      mockStorage.getSites.mockRejectedValue(new Error('Connection refused'));
      
      await expect(mockStorage.getSites()).rejects.toThrow('Connection refused');
    });

    it('should include uptime in response', () => {
      const uptime = process.uptime();
      
      expect(uptime).toBeGreaterThanOrEqual(0);
    });
  });
});

